public static class StationArchiveText
{
    public static string Resolve(string title,string fallback)
    {
        switch(title)
        {
            case "НЕЗАВЕРШЁННЫЙ ЦИКЛ":return "Журнал инкубационного зала. Смена 184.\n\nВедомость отмечает партию как завершённую. Внутри сосудов по-прежнему нет ни одного самостоятельного импульса. Оболочки принимают питание, восстанавливают повреждения и поворачиваются к источнику звука. Этого недостаточно, чтобы назвать их живыми.\n\nНачальник смены запретил извлекать неудачные экземпляры. Станция продолжает учитывать их как сотрудников. На каждую пустую оболочку выделены место в колыбели и порция проводящей жидкости.\n\nПриписка от руки: «Сегодня один сосуд оказался пуст. Замок не повреждён. В реестре появилась новая отметка: вернулся к работе».";
            case "КРОВЬ МАШИНЫ":return "Служба циркуляции. Отклонение давления.\n\nНасосы питают не только Нижние сады. Та же жидкость проходит через стены, инкубаторы и нервные нити подъёмников. Отключение магистрали остановит половину станции, даже если двигатели ещё будут вращаться.\n\nСадовник-07 получил право закрывать контур при угрозе заражения. Приказ о карантине подтверждён, но подпись оператора отсутствует. Последующие команды на открытие страж распознаёт как повреждённые.\n\nАварийный сброс направлен в сосудистый пояс. Оттуда приходит обратный импульс с постоянным интервалом. Он не совпадает с ритмом ни одного нашего насоса.";
            case "ТИШИНА НАД САДАМИ":return "Синаптическая обсерватория. Последний сеанс.\n\nПриёмник слушал поселения за внешней оболочкой. После третьего провала связи антенну повернули внутрь станции: техник решил проверить, не глушат ли сигнал корневые линии.\n\nОтвет пришёл снизу. Пять коротких импульсов, длинная пауза, затем ещё один — слабее остальных. Когда питание приёмника отключили, последовательность продолжилась в резервной цепи.\n\nСтарший наблюдатель приказал не отвечать. В журнале исходящих передач уже есть ответ, отправленный за одиннадцать минут до приёма сигнала.\n\nЛичная запись: «Мне кажется, это не зов. Кто-то пересчитывает тех, кто ещё остался».";
            case "АРХИВ ПАРТИИ 09":return "Партия 09. Акт консервации.\n\nОболочки выращивали из общей матрицы, но каждая должна была сохранить собственную память. После синхронизации воспоминания стали повторяться: один коридор, одна закрытая дверь, одна рука по другую сторону стекла.\n\nКомиссия признала матрицу повреждённой. Оболочки разобрали, а уцелевшие пластины оставили в изолированных отсеках. Их внутренние каналы до сих пор соединяются без швов.\n\nТри совместимых фрагмента способны замкнуть дополнительный защитный контур. Не используйте материал из разных партий.\n\nВ конце акта нет подписей. Девять одинаковых отпечатков пальцев нанесены поверх графы «ответственный».";
            case "ОБРАТНЫЙ ТОК":return "Резервуар обратного тока. Памятка дежурному.\n\nНе перекрывайте нижний отвод полностью. Давление должно уходить в сосудистый пояс, иначе накопленный импульс вернётся в инкубаторы. При отключённой связи выполняйте эту процедуру вручную.\n\nНа стенках резервуара обнаружена ткань, которой нет в спецификации станции. Она сокращается до запуска насосов, словно заранее знает, когда начнётся очередной цикл.\n\nПосле закрытия садов нижние клапаны остались открыты. По трубам теперь движется что-то против потока. Датчики показывают норму: система считает это возвращением обслуживающего персонала.\n\nПриписка: «Если услышишь стук из пустой трубы, не стучи в ответ».";
            case "СОСУДИСТЫЙ ПРЕДЕЛ":return "Пограничный пост. Доступ к нижней магистрали.\n\nЗдесь заканчиваются контуры, нанесённые на план станции. Дальше опоры обрастают проводящей тканью, а маркировка исчезает быстрее, чем её успевают восстанавливать.\n\nПервая экспедиция доложила о втором пульсе под основным. Вторая оставила инструменты у входа. Третью отменили, однако подъёмник зарегистрировал отправление полного состава.\n\nПротокол возврата требует сверять память, а не внешний вид оболочки. На вопрос «откуда ты пришёл?» все вернувшиеся отвечали одинаково: «сверху».\n\nКарантинный замок связан с контуром Садовника. Если путь открылся, охрана станции больше не контролирует эту границу.";
            default:return fallback;
        }
    }
}
